+fn do_import(w: &World, h: &mut History, items: &[(&str, Tool)], mode: ImportMode) -> Result<String, String> {
+    let cmd = ImportTools::with_mode(w, lib(items), mode).map_err(|e| e.to_string())?;
+    let s = cmd.report().summary();
+    h.execute(w, cmd);
